// Função utilitária para limpar os dados de teste
async function cleanupTestData(userId) {
  if (!userId) return;

  try {
    // Lista de tabelas a serem limpas para o usuário específico
    const tables = [
      'tasks',
      'user_priorities',
      'time_blocks', 
      'medications',
      'sleep_logs',
      'mood_logs',
      'finance_transactions',
      'finance_categories',
      'finance_envelopes'
    ];
    
    // Executar deleção em paralelo para todas as tabelas
    await Promise.all(
      tables.map(table => 
        supabase
          .from(table)
          .delete()
          .eq('user_id', userId)
          .eq('teste', true) // Só limpar registros marcados como teste
      )
    );
    
    console.log(`Dados de teste limpos para o usuário ${userId}`);
  } catch (error) {
    console.error('Erro ao limpar dados de teste:', error);
  }
}

// Função para verificar o status da conexão
async function checkConnection() {
  try {
    const { data, error } = await supabase.from('user_profiles').select('count').limit(1);
    if (error) throw error;
    return { connected: true, data };
  } catch (error) {
    return { connected: false, error: error.message };
  }
}

module.exports = { supabase, cleanupTestData, checkConnection, createSupabaseClient, MemoryStorage };
